# ---------------------- Project and coordinate utilities ----------------------
def clone(value):
    return copy.deepcopy(value)

def batch_progress(callback,completed,total,label=''):
    if callback is None:return None
    def emit(value):
        callback(dict(message=(label+' · ' if label else '')+value['message'],
                      percent=95*(completed+value['percent']/100)/max(1,total)))
    return emit

def xyz(a):
    return np.array([a['x'],a['y'],a['z']],dtype=float)

def set_xyz(a,p):
    a.update(zip(('x','y','z'),map(float,p)))

def unit(v, fallback=(1.,0.,0.)):
    v=np.asarray(v,dtype=float);n=np.linalg.norm(v)
    return v/n if n>1.e-10 else np.asarray(fallback,dtype=float)

def bond_key(a,b):
    return tuple(sorted((int(a),int(b))))

def index_atoms(p):
    return {a['id']:a for a in p['atoms']}

def adjacency(p):
    out={a['id']:[] for a in p['atoms']}
    for b in p['bonds']:
        out[b['a']].append(b['b']);out[b['b']].append(b['a'])
    return out

def add_bond(p,a,b,order=1.,kind='covalent',source='user'):
    if a==b: raise ValueError('같은 원자끼리 연결할 수 없습니다.')
    old=next((v for v in p['bonds'] if bond_key(v['a'],v['b'])==bond_key(a,b)),None)
    data={'a':int(a),'b':int(b),'order':float(order),'kind':kind,'source':source}
    if old: old.update(data)
    else: p['bonds'].append(data)
    return old or data

def validate_project(p):
    if not isinstance(p,dict) or not isinstance(p.get('atoms'),list) or not isinstance(p.get('bonds'),list):
        raise ValueError('유효한 프로젝트 형식이 아닙니다.')
    if len(p['atoms'])>10000: raise ValueError('대화형 편집기는 10,000원자까지 지원합니다.')
    ids=set()
    for a in p['atoms']:
        if not isinstance(a.get('id'),int) or a['id']<1 or a['id'] in ids: raise ValueError('원자 ID 중복 또는 오류')
        if a.get('element') not in SYMBOLS or not np.isfinite(xyz(a)).all(): raise ValueError('원소 또는 좌표 오류')
        ids.add(a['id'])
    pairs=set()
    for b in p['bonds']:
        k=bond_key(b['a'],b['b'])
        if not set(k)<=ids or k[0]==k[1] or k in pairs: raise ValueError('중복되거나 존재하지 않는 원자 결합')
        if float(b.get('order',1)) not in (0.,1.,1.5,2.,3.): raise ValueError('지원하지 않는 결합차수')
        pairs.add(k)
    p.setdefault('slots',[]);p.setdefault('metadata',{});p.setdefault('title','Tin oxo structure')
    for s in p['slots']:
        if not set(s.get('sn',[]))<=ids: raise ValueError('결합 자리의 부모 원자가 없습니다.')
    return p

def template(n):
    p=clone(DATA['templates'][str(n)])
    p['slots']=[s for s in p['slots'] if s['kind']!='X']
    p['title']=f'Sn{n} oxo cluster'
    p['version']=3
    for b in p['bonds']: b.update(source='literature',kind='core')
    if n==3:
        # Keep exactly the alternating Sn–O ring, deleting rather than hiding the cap and H.
        remove={4,8,9,10}
        p['atoms']=[a for a in p['atoms'] if a['id'] not in remove]
        p['bonds']=[b for b in p['bonds'] if not ({b['a'],b['b']}&remove)]
        p['metadata'].update(formula='Sn3O3 backbone',status='Sn3O3 ring / user design',
            totalCharge=None,requiresChargeReview=True,
            coordinateNote='원래 Sn3O(OH)3 좌표에서 μ3-O와 OH의 H를 실제 제거한 Sn3O3 고리. 문헌 완성 화합물과 다른 불완전 설계 골격이며 전하/산화상태는 미지정.',protonation='bare Sn3O3; no H')
    p['metadata'].setdefault('requiresChargeReview',True)
    return validate_project(p)

def formula(p):
    c=Counter(a['element'] for a in p['atoms'])
    keys=(['C','H']+[s for s in sorted(c) if s not in ('C','H')]) if c.get('C') else sorted(c)
    return ''.join(s+(str(c[s]) if c[s]>1 else '') for s in keys if c[s])

def atomic_write(path,text):
    path=Path(path).expanduser();path.parent.mkdir(parents=True,exist_ok=True)
    fd,name=tempfile.mkstemp(prefix='.'+path.name+'.',dir=path.parent)
    try:
        with os.fdopen(fd,'w',encoding='utf-8',newline='\n') as f: f.write(text);f.flush();os.fsync(f.fileno())
        os.replace(name,path)
    finally:
        if os.path.exists(name):os.unlink(name)

def delete_atoms(p,ids):
    removed=set(ids);p['atoms']=[a for a in p['atoms'] if a['id'] not in removed]
    p['bonds']=[b for b in p['bonds'] if not ({b['a'],b['b']}&removed)]
    alive={a['id'] for a in p['atoms']};slots=[]
    for s in p['slots']:
        if not set(s.get('sn',[]))<=alive: continue
        s['ligandIds']=[i for i in s.get('ligandIds',[]) if i in alive]
        if s.get('smiles') and not s['ligandIds']:
            for k in ('smiles','anchor','donorIds','centerAtom','fragmentCharge','attachmentIndex','placement'):s.pop(k,None)
            if s.get('custom'):continue
        slots.append(s)
    p['slots']=slots
    for a in p['atoms']:
        if a.get('slot') and not any(s['id']==a['slot'] for s in slots):a.pop('slot',None)
    p['metadata']['requiresChargeReview']=True

def clear_slot(p,slot_id):
    groups={slot_id}
    while True:
        ids={a['id'] for a in p['atoms'] if a.get('slot') in groups}
        more={s['id'] for s in p['slots'] if s.get('custom') and set(s.get('sn',[]))&ids}
        if more<=groups:break
        groups |= more
    delete_atoms(p,[a['id'] for a in p['atoms'] if a.get('slot') in groups])
    p['slots']=[s for s in p['slots'] if s['id'] not in groups or not s.get('custom')]
    for s in p['slots']:
        if s['id']==slot_id:
            for k in ('smiles','ligandIds','anchor','donorIds','centerAtom','fragmentCharge','resonance','attachmentIndex','placement'):
                s.pop(k,None)

def excluded_pairs(p):
    g=adjacency(p);out=set()
    for a,ns in g.items():
        for n in ns:
            out.add(bond_key(a,n))
            for n2 in g[n]:out.add(bond_key(a,n2))
    return out

def radius(element,kind='covalent'):
    z=atomic_numbers[element]
    try:r=PT.GetRcovalent(element) if kind=='covalent' else PT.GetRvdw(element)
    except Exception:r=float(covalent_radii[z]) if kind=='covalent' else 1.8
    return r if math.isfinite(r) and r>0 else (1.5 if kind=='covalent' else 2.)

def contact_cut(a,b,c):
    if c.get('mode')=='minimum':return float(c.get('minimum',2.))
    return max(float(c.get('vdw',.75))*(radius(a['element'],'vdw')+radius(b['element'],'vdw')),
               float(c.get('covalent',1.18))*(radius(a['element'])+radius(b['element'])))

def clashes(p,criteria=None):
    c=criteria or p['metadata'].get('contactCriteria',DEFAULTS['contact']);out=[];ex=excluded_pairs(p)
    # Spatial indexing, instead of allocating an N×N matrix for a large ligand bank.
    from scipy.spatial import cKDTree
    if len(p['atoms'])<2:return out
    aa=p['atoms'];points=np.array([xyz(a) for a in aa])
    maxcut=max(float(c.get('minimum',2.)),2*max(radius(a['element'],'vdw') for a in aa)*float(c.get('vdw',.75)),
        2*max(radius(a['element']) for a in aa)*float(c.get('covalent',1.18)))
    for i,j in sorted(cKDTree(points).query_pairs(maxcut)):
        a,b=aa[i],aa[j]
        if bond_key(a['id'],b['id']) in ex or a.get('core') and b.get('core'):continue
        d=float(np.linalg.norm(points[i]-points[j]));cut=contact_cut(a,b,c)
        if d<cut:out.append({'a':a['id'],'b':b['id'],'distance':d,'threshold':cut})
    return sorted(out,key=lambda r:r['distance']-r['threshold'])

def measurement(p,ids,atom_index=None):
    if len(set(ids))!=len(ids) or not 2<=len(ids)<=4:raise ValueError('서로 다른 원자 2, 3, 4개를 순서대로 선택하세요.')
    a=atom_index if atom_index is not None else index_atoms(p);r=[xyz(a[i]) for i in ids]
    if len(r)==2:return ('거리',float(np.linalg.norm(r[0]-r[1])),'Å')
    u,v=r[0]-r[1],r[2]-r[1]
    if min(np.linalg.norm(u),np.linalg.norm(v))<1.e-9:raise ValueError('겹친 원자는 각도를 정의할 수 없습니다.')
    if len(r)==3:return ('결합각',math.degrees(math.acos(float(np.clip(np.dot(unit(u),unit(v)),-1,1)))),'°')
    b0=r[0]-r[1];b1=unit(r[2]-r[1]);b2=r[3]-r[2]
    v=b0-np.dot(b0,b1)*b1;w=b2-np.dot(b2,b1)*b1
    if min(np.linalg.norm(v),np.linalg.norm(w))<1.e-9:raise ValueError('일직선 원자에서는 이면각이 정의되지 않습니다.')
    return ('이면각',math.degrees(math.atan2(np.dot(np.cross(b1,v),w),np.dot(v,w))),'°')

def geometry_rows(p):
    a=index_atoms(p);g=adjacency(p);rows=[]
    for b in p['bonds']:
        ids=[b['a'],b['b']];kind,value,unit_=measurement(p,ids,a)
        rows.append(('거리','–'.join(a[i]['element']+str(i) for i in ids),value,unit_,b.get('source','explicit')))
    for center,ns in g.items():
        for u,v in itertools.combinations(ns,2):
            try:
                ids=[u,center,v];kind,value,unit_=measurement(p,ids,a)
                rows.append(('각도','–'.join(a[i]['element']+str(i) for i in ids),value,unit_,'explicit graph'))
            except ValueError:pass
    return rows

