def resonance_info(mol,max_forms=64):
    """Enumerate Lewis representations. Arithmetic averages are display metadata only."""
    if mol.GetNumAtoms()>350:return {'forms':1,'truncated':True,'bonds':{},'smiles':[]}
    supplier=Chem.ResonanceMolSupplier(mol,0,max_forms)
    forms=list(supplier)
    if not forms:forms=[mol]
    changes={}
    for b in mol.GetBonds():
        i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
        orders=[float(m.GetBondBetweenAtoms(i,j).GetBondTypeAsDouble()) for m in forms]
        if b.GetIsAromatic() or b.GetIsConjugated() or max(orders)-min(orders)>.1:
            changes[f'{i}:{j}']={'meanFormalOrder':float(np.mean(orders)), 'range':[min(orders),max(orders)],'conjugated':b.GetIsConjugated()}
    return {'forms':len(forms),'truncated':len(forms)>=max_forms,'bonds':changes,
        'smiles':[Chem.MolToSmiles(m,canonical=False) for m in forms[:16]]}

def make_forcefield(mol,choice,conf_id=-1):
    if choice=='MMFF94':
        if not AllChem.MMFFHasAllMoleculeParams(mol):raise ValueError('MMFF94 파라미터가 없는 원자가 있습니다. UFF 지원 여부를 확인하거나 유기 리간드만 최적화하세요.')
        props=AllChem.MMFFGetMoleculeProperties(mol,mmffVariant='MMFF94')
        ff=AllChem.MMFFGetMoleculeForceField(mol,props,confId=conf_id,ignoreInterfragInteractions=False)
    elif choice=='UFF':
        if not AllChem.UFFHasAllMoleculeParams(mol):raise ValueError('UFF 파라미터가 없는 원자/배위 환경입니다. 이 구조에 UFF를 적용하지 않았습니다.')
        ff=AllChem.UFFGetMoleculeForceField(mol,confId=conf_id,ignoreInterfragInteractions=False)
    else:raise ValueError('힘장은 MMFF94 또는 UFF를 선택하세요.')
    if ff is None:raise ValueError('힘장 객체를 생성하지 못했습니다.')
    return ff

def minimize_ff(ff,steps=500,cancel=None,progress=None):
    ff.Initialize();before=float(ff.CalcEnergy());status=1
    for done in range(0,steps,25):
        if cancel and cancel.is_set():raise InterruptedError('최적화를 취소했습니다.')
        count=min(25,steps-done)
        status=ff.Minimize(maxIts=count,forceTol=1.e-4,energyTol=1.e-6)
        if progress:progress(dict(message=f'힘장 반복 예산 {min(done+count,steps)}/{steps}',percent=95*min(done+count,steps)/steps))
        if status==0:break
    after=float(ff.CalcEnergy())
    if not math.isfinite(after):raise ValueError('힘장 계산이 유한한 에너지를 반환하지 않았습니다.')
    return before,after,status

def initial_resonance_restraints(mol,ff,choice):
    """Constrain equivalent terminal O in isolated carboxylate/nitro groups.

    UFF treats a single Lewis graph literally. Use RDKit MMFF equilibrium
    distances for these narrowly identified symmetric groups, never all
    resonance bonds and never asymmetric metal-bound donors.
    """
    if choice!='UFF' or not AllChem.MMFFHasAllMoleculeParams(mol):return []
    props=AllChem.MMFFGetMoleculeProperties(mol,mmffVariant='MMFF94');notes=[]
    for center in mol.GetAtoms():
        oxy=[a for a in center.GetNeighbors() if a.GetAtomicNum()==8 and a.GetDegree()==1 and a.GetTotalNumHs()==0]
        if len(oxy)!=2 or center.GetAtomicNum() not in (6,7):continue
        if oxy[0].GetIsotope()!=oxy[1].GetIsotope():continue
        orders=sorted(mol.GetBondBetweenAtoms(center.GetIdx(),a.GetIdx()).GetBondTypeAsDouble() for a in oxy)
        total=center.GetFormalCharge()+sum(a.GetFormalCharge() for a in oxy)
        is_equivalent=(center.GetAtomicNum()==6 and total==-1) or (center.GetAtomicNum()==7 and center.GetFormalCharge()==1 and total==0)
        if orders!=[1.,2.] or not is_equivalent:continue
        pars=[props.GetMMFFBondStretchParams(mol,center.GetIdx(),a.GetIdx()) for a in oxy]
        if any(p is None for p in pars):continue
        target=float(np.mean([p[2] for p in pars]))
        for a in oxy:ff.UFFAddDistanceConstraint(center.GetIdx(),a.GetIdx(),False,target,target,100000.)
        notes.append({'center':center.GetIdx(),'oxygen':[a.GetIdx() for a in oxy],'target_A':target,'reference':'RDKit MMFF94 equilibrium distances'})
    return notes

def rigid_fit(points,targets):
    x=np.asarray(points);y=np.asarray(targets);xc=x.mean(0);yc=y.mean(0)
    u,s,vt=np.linalg.svd((x-xc).T@(y-yc));r=u@vt
    if np.linalg.det(r)<0:u[:,-1]*=-1;r=u@vt
    return r,xc,yc

def rotate_matrix(source,target):
    u,v=unit(source),unit(target);c=float(np.clip(np.dot(u,v),-1,1));cross=np.cross(u,v);s=np.linalg.norm(cross)
    if s<1.e-9:
        if c>0:return np.eye(3)
        axis=unit(np.cross(u,(0,1,0) if abs(u[1])<.8 else (1,0,0)))
        return 2*np.outer(axis,axis)-np.eye(3)
    k=np.array([[0,-cross[2],cross[1]],[cross[2],0,-cross[0]],[-cross[1],cross[0],0]])
    return np.eye(3)+k+k@k*((1-c)/(s*s))

def axis_rotation(axis,angle):
    x,y,z=unit(axis);k=np.array([[0,-z,y],[z,0,-x],[-y,x,0]])
    return np.eye(3)+math.sin(angle)*k+(1-math.cos(angle))*(k@k)

def ligand_attachment_info(smiles,kind='A',mode='covalent'):
    """Indices always refer to the original RDKit SMILES graph, before AddHs.

    Keep this graph unchanged between the 2D picker and 3D construction so
    branching, atom maps and stereochemistry cannot silently move the anchor.
    """
    mol=Chem.MolFromSmiles(smiles.strip())
    if mol is None:raise ValueError('RDKit이 SMILES를 해석하지 못했습니다. 전하·괄호·결합차수를 확인하세요.')
    if len(Chem.GetMolFrags(mol))!=1:raise ValueError('한 입력줄에는 연결된 리간드 한 개만 입력하세요. 반대이온은 별도 성분으로 추가할 수 있습니다.')
    if any(a.GetSymbol() in METALS for a in mol.GetAtoms()):raise ValueError('리간드 생성은 유기/비금속 조각을 대상으로 합니다. 금속 포함 구조는 MOL/SDF로 불러오세요.')
    if mol.GetNumAtoms()>800:raise ValueError('리간드는 H 포함 800원자까지 생성합니다.')
    stars=[a.GetIdx() for a in mol.GetAtoms() if a.GetAtomicNum()==0]
    groups=[]
    if kind in ('L','P'):
        if stars:raise ValueError('가교 L/P 자리는 * 없이 카복실레이트/포스피네이트 전체를 입력하세요.')
        for a in mol.GetAtoms():
            oxy=[n for n in a.GetNeighbors() if n.GetSymbol()=='O']
            if a.GetSymbol()==('C' if kind=='L' else 'P') and len(oxy)==2 and any(mol.GetBondBetweenAtoms(a.GetIdx(),n.GetIdx()).GetBondTypeAsDouble()>=2 for n in oxy):
                if all(all(n.GetIdx()==a.GetIdx() or n.GetAtomicNum()==1 for n in o.GetNeighbors()) for o in oxy):
                    groups.append((a.GetIdx(),[n.GetIdx() for n in oxy]))
        if not groups:raise ValueError('C(=O)[O-] 또는 P(=O)([O-])(R)R 연결부가 필요합니다.')
        candidates=[i for _,oxy in groups for i in oxy];default=candidates[0]
    else:
        if len(stars)>1:raise ValueError('말단 [*:1] 하나만 사용하세요.')
        if stars and mol.GetAtomWithIdx(stars[0]).GetDegree()!=1:raise ValueError('*는 연결점 하나를 가진 말단 원자여야 합니다.')
        marked=mol.GetAtomWithIdx(stars[0]).GetNeighbors()[0].GetIdx() if stars else None
        candidates=[a.GetIdx() for a in mol.GetAtoms() if a.GetAtomicNum()>1
                    and (kind!='R' or a.GetSymbol()=='C')
                    and (mode=='coordinate' or a.GetTotalNumHs()>0 or any(n.GetAtomicNum()==1 for n in a.GetNeighbors()) or a.GetIdx()==marked)]
        default=marked if marked in candidates else (candidates[0] if candidates else None)
    if not candidates:raise ValueError('이 방식으로 결합할 원자가 없습니다. 공유결합에는 치환할 H 또는 *가 필요합니다. 배위결합은 coordinate를 선택하세요.')
    return {'mol':mol,'candidates':candidates,'default':default,'groups':groups,'stars':stars}


def build_fragment(smiles,kind='A',mode='covalent',ff_choice='MMFF94',conformers=6,cancel=None,attachment_index=None,progress=None):
    if cancel and cancel.is_set():raise InterruptedError('리간드 생성을 취소했습니다.')
    if progress:progress(dict(message='SMILES·결합 원자 검증',percent=0))
    info=ligand_attachment_info(smiles,kind,mode);mol=info['mol'];stars=info['stars']
    # Legacy calls without a picker retain their first-atom / dummy behavior.
    if attachment_index is None:
        if kind in ('L','P'):
            if len(info['groups'])!=1:raise ValueError('가교 연결부가 여러 개입니다. 팝업에서 donor O를 선택하세요.')
            anchor=info['default']
        else:anchor=mol.GetAtomWithIdx(stars[0]).GetNeighbors()[0].GetIdx() if stars else 0
    else:
        if isinstance(attachment_index,bool) or not isinstance(attachment_index,(int,np.integer)):raise ValueError('리간드 원자 번호는 정수여야 합니다.')
        anchor=int(attachment_index)
    if anchor not in info['candidates']:raise ValueError('선택한 원자는 이 결합 방식에 사용할 수 없습니다. 팝업에서 결합 원자를 다시 선택하세요.')
    selected_index=anchor
    cap=None;donors=[];center=None
    if kind in ('L','P'):
        center,oxy=next((c,ds) for c,ds in info['groups'] if anchor in ds)
        donors=[anchor]+[i for i in oxy if i!=anchor];rw=Chem.RWMol(mol)
        for i in donors:
            o=rw.GetAtomWithIdx(i)
            if any(n.GetIdx()!=center for n in o.GetNeighbors()):raise ValueError('가교 donor O에 에스터/추가 치환기가 있습니다.')
            if rw.GetBondBetweenAtoms(center,i).GetBondTypeAsDouble()==1:
                o.SetFormalCharge(-1);o.SetNumExplicitHs(0);o.SetNoImplicit(True)
        mol=rw.GetMol();Chem.SanitizeMol(mol);anchor=donors[0]
    else:
        if stars:
            marked=mol.GetAtomWithIdx(stars[0]).GetNeighbors()[0].GetIdx()
            rw=Chem.RWMol(mol);h=Chem.Atom(1);h.SetNoImplicit(True);rw.ReplaceAtom(stars[0],h);mol=rw.GetMol();Chem.SanitizeMol(mol)
            if anchor==marked and mode=='covalent':cap=stars[0]
        if kind=='R' and mol.GetAtomWithIdx(anchor).GetSymbol()!='C':raise ValueError('R 자리는 Sn–C 결합입니다. 탄소 연결점의 SMILES를 입력하세요.')
    res=resonance_info(mol)
    mol=Chem.AddHs(mol)
    if cap is None and kind not in ('L','P') and mode=='covalent':
        hs=[a.GetIdx() for a in mol.GetAtomWithIdx(anchor).GetNeighbors() if a.GetAtomicNum()==1]
        if not hs:raise ValueError('공유결합 연결점에 치환할 H가 없습니다. [*:1]로 연결점을 지정하세요.')
        cap=hs[0]
    if mol.GetNumAtoms()>800:raise ValueError('리간드는 H 포함 800원자까지 생성합니다.')
    params=AllChem.ETKDGv3();params.randomSeed=87321;params.numThreads=1;params.enforceChirality=True
    params.pruneRmsThresh=.15
    if progress:progress(dict(message='명시적 H 준비 완료 · 3D conformer 생성',percent=10))
    ids=list(AllChem.EmbedMultipleConfs(mol,numConfs=max(1,conformers),params=params))
    if not ids:
        params.useRandomCoords=True;ids=list(AllChem.EmbedMultipleConfs(mol,numConfs=1,params=params))
    if not ids:raise ValueError('ETKDG 3D 좌표 생성에 실패했습니다. 리간드를 나누거나 구조 파일을 사용하세요.')
    results=[];restraint_notes=[]
    for k,ci in enumerate(ids):
        if progress:progress(dict(message=f'conformer {k+1}/{len(ids)} 힘장 정리',percent=25+70*k/len(ids)))
        if mol.GetNumAtoms()-(1 if cap is not None else 0)==1:
            # A single attached atom has no internal coordinates to optimize.
            results.append((0.,ci,0));continue
        ff=make_forcefield(mol,ff_choice,ci)
        restraint_notes=initial_resonance_restraints(mol,ff,ff_choice)
        def conf_progress(value):
            if progress:progress(dict(message=f'conformer {k+1}/{len(ids)} · '+value['message'],percent=25+70*(k+value['percent']/100)/len(ids)))
        before,after,status=minimize_ff(ff,400,cancel,conf_progress);results.append((after,ci,status))
    e,ci,status=min(results,key=lambda r:r[0]);conf=mol.GetConformer(ci)
    points=np.asarray(conf.GetPositions(),dtype=float)
    if cap is not None:direction=unit(points[anchor]-points[cap])
    else:
        neighbors=[n.GetIdx() for n in mol.GetAtomWithIdx(anchor).GetNeighbors()]
        direction=unit(sum((points[anchor]-points[j] for j in neighbors),np.zeros(3)))
    keep=[i for i in range(mol.GetNumAtoms()) if i!=cap];atoms=[]
    for i in keep:
        a=mol.GetAtomWithIdx(i);r=points[i]
        atoms.append({'id':i,'element':a.GetSymbol(),'x':float(r[0]),'y':float(r[1]),'z':float(r[2]),
            'charge':a.GetFormalCharge(),'radical':a.GetNumRadicalElectrons(),'isotope':a.GetIsotope(),
            'aromatic':a.GetIsAromatic(),'chirality':int(a.GetChiralTag()),'core':False,'fixed':False})
    bonds=[]
    for b in mol.GetBonds():
        i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
        if cap in (i,j):continue
        data={'a':i,'b':j,'order':float(b.GetBondTypeAsDouble()),'source':'RDKit SMILES','kind':'covalent'}
        if b.GetIsAromatic():data['order']=1.5
        ri=res['bonds'].get(f'{i}:{j}') or res['bonds'].get(f'{j}:{i}')
        if ri:data['resonance']=ri
        bonds.append(data)
    if progress:progress(dict(message='리간드 3D 생성 완료',percent=100))
    return {'atoms':atoms,'bonds':bonds,'anchor':anchor,'center':center,'donors':donors,
        'direction':direction,'resonance':res,'smiles':smiles,'attachmentIndex':selected_index,'energy':e,'status':status,
        'charge':sum(a['charge'] for a in atoms),'conformers':len(ids),'ff':ff_choice,
        'resonanceRestraints':restraint_notes}


def placement_score(p,new_atoms,new_bonds):
    test={'atoms':p['atoms']+new_atoms,'bonds':p['bonds']+new_bonds,'slots':p['slots'],'metadata':p['metadata']}
    ids={a['id'] for a in new_atoms};c=p['metadata'].get('contactCriteria',DEFAULTS['contact'])
    return sum((v['threshold']-v['distance'])**2 for v in clashes(test,c) if v['a'] in ids or v['b'] in ids)

class PlacementScorer:
    """Exact rigid-pose contact score; reuse graph, radii and static environment.

    Intrafragment distances do not change under rigid rotation. Only cross
    distances need evaluating for each pose. Large environments use a KD-tree;
    small pairs use NumPy, avoiding repeated graph/tree construction entirely.
    """
    def __init__(self,p,new_atoms,new_bonds):
        from scipy.spatial import cKDTree
        self.criteria=p['metadata'].get('contactCriteria',DEFAULTS['contact'])
        self.old=p['atoms'];self.new=new_atoms
        self.old_xyz=np.array([xyz(a) for a in self.old],dtype=float).reshape(-1,3)
        self.excluded=excluded_pairs(dict(atoms=self.old+new_atoms,bonds=p['bonds']+new_bonds))
        elements={a['element'] for a in self.old+new_atoms}
        self.radii={s:(radius(s,'vdw'),radius(s)) for s in elements}
        self.old_r=np.array([self.radii[a['element']] for a in self.old],dtype=float).reshape(-1,2)
        self.new_r=np.array([self.radii[a['element']] for a in new_atoms],dtype=float).reshape(-1,2)
        self.dense=len(self.old)*len(new_atoms)<=250000
        if self.dense:
            self.cuts=self.cutoffs(self.new_r[:,None,:],self.old_r[None,:,:])
            self.allowed=np.array([[bond_key(a['id'],b['id']) not in self.excluded and not(a.get('core') and b.get('core')) for b in self.old] for a in new_atoms],dtype=bool).reshape(len(new_atoms),len(self.old))
        else:
            self.tree=cKDTree(self.old_xyz)
            self.maxcut=float(np.max(self.cutoffs(self.new_r.max(axis=0),self.old_r.max(axis=0))))
        points=np.array([xyz(a) for a in new_atoms])
        # Spatial pairs also bound memory for a large, sparse ligand fragment.
        self.internal=0.
        if len(new_atoms)>1:
            maxcut=float(self.cutoffs(self.new_r.max(axis=0),self.new_r.max(axis=0)))
            pairs=cKDTree(points).query_pairs(maxcut,output_type='ndarray')
            if len(pairs):
                i,j=pairs[:,0],pairs[:,1]
                allowed=np.array([bond_key(new_atoms[u]['id'],new_atoms[v]['id']) not in self.excluded and not(new_atoms[u].get('core') and new_atoms[v].get('core')) for u,v in pairs],dtype=bool)
                distances=np.linalg.norm(points[i]-points[j],axis=1)
                overlap=np.maximum(0,self.cutoffs(self.new_r[i],self.new_r[j])-distances)
                self.internal=float(np.sum(overlap[allowed]**2))
    def cutoffs(self,a,b):
        c=self.criteria
        if c.get('mode')=='minimum':return np.full(np.broadcast_shapes(a.shape[:-1],b.shape[:-1]),float(c.get('minimum',2.)))
        return np.maximum((a[...,0]+b[...,0])*float(c.get('vdw',.75)),(a[...,1]+b[...,1])*float(c.get('covalent',1.18)))
    def score(self,points):
        if not len(self.old):return self.internal
        if self.dense:
            delta=np.asarray(points)[:,None,:]-self.old_xyz[None,:,:]
            distances=np.sqrt(np.einsum('ijk,ijk->ij',delta,delta))
            overlap=np.maximum(0,self.cuts-distances)
            return self.internal+float(np.sum(overlap[self.allowed]**2))
        neighbors=self.tree.query_ball_point(points,self.maxcut)
        pairs=[(i,j) for i,ns in enumerate(neighbors) for j in ns if bond_key(self.new[i]['id'],self.old[j]['id']) not in self.excluded and not(self.new[i].get('core') and self.old[j].get('core'))]
        if not pairs:return self.internal
        ix=np.asarray(pairs,dtype=int);i,j=ix[:,0],ix[:,1]
        overlap=np.maximum(0,self.cutoffs(self.new_r[i],self.old_r[j])-np.linalg.norm(np.asarray(points)[i]-self.old_xyz[j],axis=1))
        return self.internal+float(np.sum(overlap**2))

def outward_direction(p,parent):
    a=index_atoms(p);g=adjacency(p);r=xyz(a[parent]);ds=[unit(r-xyz(a[n])) for n in g[parent]]
    return unit(sum(ds,np.zeros(3)),unit(r-np.mean([xyz(v) for v in p['atoms']],axis=0)))

def attach_fragment(p,smiles,parent=None,slot_id=None,mode='covalent',length=None,direction=None,
                    replace_h=True,ff_choice='MMFF94',cleanup=True,cancel=None,attachment_index=None,fragment_cache=None,progress=None):
    # A failed exterior-pose search must not erase an old slot or its OH/H.
    before=clone(p)
    try:return _attach_fragment(p,smiles,parent,slot_id,mode,length,direction,replace_h,ff_choice,cleanup,cancel,attachment_index,fragment_cache,progress)
    except Exception:
        p.clear();p.update(before);raise


def _attach_fragment(p,smiles,parent=None,slot_id=None,mode='covalent',length=None,direction=None,
                    replace_h=True,ff_choice='MMFF94',cleanup=True,cancel=None,attachment_index=None,fragment_cache=None,progress=None):
    slot=next((s for s in p['slots'] if s['id']==slot_id),None) if slot_id else None
    if slot_id and slot is None:raise ValueError('결합 자리가 없습니다.')
    if slot:
        kind=slot['kind'];parents=list(slot['sn']);slot_copy=clone(slot)
        if attachment_index is None and smiles==slot.get('smiles'):attachment_index=slot.get('attachmentIndex')
        clear_slot(p,slot_id)
        slot=next((s for s in p['slots'] if s['id']==slot_id),None)
        if slot is None:slot=slot_copy;p['slots'].append(slot)
    else:
        kind='A';parents=[int(parent)]
        slot_id='U'+str(max([int(s['id'][1:]) for s in p['slots'] if re.fullmatch(r'U\d+',s['id'])]+[0])+1)
        slot={'id':slot_id,'kind':'A','sn':parents,'custom':True,'position':xyz(index_atoms(p)[parent]).tolist()}
        p['slots'].append(slot)
    if not smiles.strip():return slot
    a=index_atoms(p)
    if any(i not in a for i in parents):raise ValueError('부모 원자가 삭제되어 리간드를 부착할 수 없습니다.')
    if any(a[i]['element']=='H' for i in parents):raise ValueError('H에 결합을 덧붙일 수 없습니다. H를 치환할 부모 원자를 선택하세요.')
    if attachment_index is not None and (isinstance(attachment_index,bool) or not isinstance(attachment_index,(int,np.integer))):raise ValueError('결합 원자 번호는 정수여야 합니다.')
    key=(smiles,kind,mode,ff_choice,attachment_index)
    frag=fragment_cache.get(key) if fragment_cache is not None else None
    if frag is None:
        def fragment_progress(value):
            if progress:progress(dict(message=value['message'],percent=.7*value['percent']))
        frag=build_fragment(smiles,kind,mode,ff_choice,conformers=4,cancel=cancel,attachment_index=attachment_index,progress=fragment_progress)
        if fragment_cache is not None:fragment_cache[key]=frag
    if progress:progress(dict(message='리간드 배치·접촉 평가',percent=70))
    if replace_h and kind=='A' and mode=='covalent' and a[parents[0]]['element'] not in METALS:
        hs=[i for i in adjacency(p)[parents[0]] if a[i]['element']=='H']
        if hs:delete_atoms(p,[hs[0]]);a=index_atoms(p)
    offset=max([v['id'] for v in p['atoms']]+[0])+1
    imap={old['id']:offset+i for i,old in enumerate(frag['atoms'])}
    new_atoms=clone(frag['atoms']);new_bonds=clone(frag['bonds'])
    for old,new in zip(frag['atoms'],new_atoms):new.update(id=imap[old['id']],slot=slot_id)
    for b in new_bonds:b['a']=imap[b['a']];b['b']=imap[b['b']]
    points=np.array([xyz(v) for v in frag['atoms']]);fi={v['id']:i for i,v in enumerate(frag['atoms'])}
    if kind in ('L','P'):
        src=np.array([points[fi[i]] for i in frag['donors']]+[points[fi[frag['center']]]])
        target=np.array(slot['donors']+[slot['center']]);r,xc,yc=rigid_fit(src,target)
        initial=(points-xc)@r+yc
        for host,donor in zip(parents,frag['donors']):
            new_bonds.append({'a':imap[donor],'b':host,'order':1.,'kind':'coordinate','source':'explicit bridge'})
        guard=CorePlacement(p,parents,new_atoms,new_bonds);scorer=PlacementScorer(p,new_atoms,new_bonds)
        donor_ix=[fi[i] for i in frag['donors']];origin=initial[donor_ix[0]];axis=initial[donor_ix[1]]-origin
        best=None;accepted=0;rejected=0
        for theta in np.linspace(0,2*math.pi,36,endpoint=False):
            if cancel and cancel.is_set():raise InterruptedError('부착을 취소했습니다.')
            fitted=(initial-origin)@axis_rotation(axis,theta).T+origin
            if not guard.safe(fitted):rejected+=1;continue
            accepted+=1
            fit=float(np.mean(np.sum((fitted[[fi[i] for i in frag['donors']]+[fi[frag['center']]]]-target)**2,axis=1)))
            score=scorer.score(fitted)+50*fit
            if best is None or score<best[0]:best=(score,fitted.copy(),fit)
            if not cleanup and theta==0:break
        if best is None:raise ValueError('코어 내부를 피하면서 두 donor 위치를 유지하는 가교 배치를 찾지 못했습니다. 연결 원자나 리간드 구조를 바꿔 다시 시도하세요.')
        slot['fitRMSD']=math.sqrt(best[2])
        for atom,rp in zip(new_atoms,best[1]):set_xyz(atom,rp)
        slot['placement']={**guard.record(),'acceptedPoses':accepted,'rejectedPoses':rejected}
        slot['donorIds']=[imap[i] for i in frag['donors']];slot['centerAtom']=imap[frag['center']]
    else:
        parent=parents[0];parent_xyz=xyz(a[parent]);anchor_xyz=points[fi[frag['anchor']]]
        length=float(length or slot.get('bondLength') or (2.15 if a[parent]['element']=='Sn' and frag['atoms'][fi[frag['anchor']]]['element']=='C' else radius(a[parent]['element'])+radius(frag['atoms'][fi[frag['anchor']]]['element'])))
        if not .5<=length<=4.:raise ValueError('부착 결합 길이는 0.50–4.00 Å이어야 합니다.')
        preferred=direction if direction is not None else slot.get('direction')
        if preferred is None:preferred=p['metadata'].get('hydroxoDirections',{}).get(str(parent))
        preferred=unit(preferred if preferred is not None else outward_direction(p,parent))
        root=imap[frag['anchor']];new_bonds.append({'a':root if mode=='coordinate' else parent,'b':parent if mode=='coordinate' else root,
            'order':1.,'kind':mode,'source':'explicit attachment'})
        guard=CorePlacement(p,parents,new_atoms,new_bonds);radial=guard.outward(parent_xyz)
        core_host=bool(a[parent].get('core'))
        if core_host and radial is None:raise ValueError('부착점이 코어 무게중심과 같아 외향 방향을 정할 수 없습니다. 코어 외곽 원자를 선택하세요.')
        if direction is not None:
            manual=np.asarray(direction,dtype=float)
            if manual.shape!=(3,) or not np.isfinite(manual).all() or np.linalg.norm(manual)<1.e-8:raise ValueError('방향은 0이 아닌 유한한 3차원 벡터여야 합니다.')
            if core_host and np.dot(preferred,radial)<-1.e-8:raise ValueError('지정한 방향이 코어 무게중심을 향합니다. 자동 또는 코어 바깥쪽 방향을 선택하세요.')
        dirs=[preferred]
        if core_host and direction is None:
            # Radial first, then only directions in the exterior cone. Old saved
            # inward directions never override this policy when re-editing.
            dirs=[radial];preferred=radial
            rotation=rotate_matrix((0,0,1),radial)
            for k in range(20):
                z=.2+.8*(k+.5)/20;phi=k*math.pi*(3-math.sqrt(5))
                dirs.append(rotation@np.array([math.sqrt(1-z*z)*math.cos(phi),math.sqrt(1-z*z)*math.sin(phi),z]))
        elif kind=='A' and direction is None:
            for k in range(20):
                z=1-2*(k+.5)/20;phi=k*math.pi*(3-math.sqrt(5));dirs.append(np.array([math.sqrt(1-z*z)*math.cos(phi),math.sqrt(1-z*z)*math.sin(phi),z]))
        best=None;scorer=PlacementScorer(p,new_atoms,new_bonds);accepted=0;rejected=0
        neighbors=adjacency(p)[parent];neighbor_dirs=[unit(xyz(a[n])-parent_xyz) for n in neighbors]
        for di,d in enumerate(dirs):
            if progress:progress(dict(message=f'부착 배향 {di+1}/{len(dirs)} 검사',percent=70+25*di/len(dirs)))
            if cancel and cancel.is_set():raise InterruptedError('부착을 취소했습니다.')
            r=rotate_matrix(frag['direction'],d);base=(points-anchor_xyz)@r.T
            angle_penalty=sum(max(0.,float(np.dot(d,nd))-.35)**2 for nd in neighbor_dirs)*25.
            for theta in np.linspace(0,2*math.pi,12 if cleanup else 1,endpoint=False):
                if cancel and cancel.is_set():raise InterruptedError('부착을 취소했습니다.')
                fitted=base@axis_rotation(d,theta).T+parent_xyz+length*d
                if not guard.safe(fitted):rejected+=1;continue
                accepted+=1
                score=scorer.score(fitted)+angle_penalty+.02*(1-float(np.dot(d,preferred)))
                if best is None or score<best[0]:best=(score,fitted.copy(),d.copy())
        if best is None:raise ValueError('코어 내부로 들어가지 않는 리간드 배치를 찾지 못했습니다. 연결 원자나 리간드 구조를 바꿔 다시 시도하세요.')
        for atom,rp in zip(new_atoms,best[1]):set_xyz(atom,rp)
        slot.update(bondLength=length,direction=best[2].tolist(),anchor=root,mode=mode)
        slot['placement']={**guard.record(),'outwardVector':radial.tolist() if radial is not None else None,
            'outwardDirectionApplied':core_host,'acceptedPoses':accepted,'rejectedPoses':rejected}
    p['atoms'].extend(new_atoms);p['bonds'].extend(new_bonds)
    slot.update(smiles=smiles,ligandIds=[v['id'] for v in new_atoms],anchor=imap[frag['anchor']],
        attachmentIndex=frag['attachmentIndex'],
        fragmentCharge=frag['charge'],resonance=frag['resonance'],resonanceRestraints=frag.get('resonanceRestraints',[]),
        geometryMethod='Single atom / no internal freedom' if len(frag['atoms'])==1 else f"RDKit ETKDGv3 + {ff_choice}"+(' + equivalent terminal-O restraints' if frag.get('resonanceRestraints') else ''))
    p['metadata']['requiresChargeReview']=True
    if kind=='A' and not a[parents[0]].get('core') and a[parents[0]]['element'] not in METALS:
        live=index_atoms(p);g=adjacency(p);component={parents[0]};todo=[parents[0]]
        while todo:
            cur=todo.pop()
            for nxt in g[cur]:
                if nxt not in component and not live[nxt].get('core') and live[nxt]['element'] not in METALS:
                    component.add(nxt);todo.append(nxt)
        project_to_rdkit(p,component,metal_dative=False,sanitize=True,cap_boundary=True)
    validate_project(p)
    if progress:progress(dict(message='리간드 부착 완료',percent=100))
    return slot


def prepare_hydroxo(p):
    if p['metadata'].get('nuclearity')!=12:raise ValueError('Sn12 코어에서 사용하는 기능입니다.')
    ref=DATA['templates']['12'];g=adjacency(ref);ra=index_atoms(ref);a=index_atoms(p);oxy=[];remove=[]
    directions=p['metadata'].setdefault('hydroxoDirections',{})
    for atom in ref['atoms']:
        if atom['element']!='H':continue
        os_=[i for i in g[atom['id']] if ra[i]['element']=='O']
        if len(os_)!=1:continue
        oid=os_[0]
        if oid in a and a[oid].get('core') and a[oid]['element']=='O':
            oxy.append(oid);directions[str(oid)]=unit(xyz(ra[oid])-xyz(atom)).tolist()
            if atom['id'] in a and a[atom['id']].get('core') and a[atom['id']]['element']=='H':remove.append(atom['id'])
    if len(set(oxy))!=6:raise ValueError('원본 Sn12 OH 자리 6개를 찾지 못했습니다. 코어 원자 ID를 확인하세요.')
    delete_atoms(p,remove)
    # Attachment direction points from O toward its removed H.
    for oid in oxy:directions[str(oid)]=(-np.asarray(directions[str(oid)])).tolist()
    return sorted(set(oxy)),remove

# --------------------- Force-field optimization and bond audit ----------------
def project_to_rdkit(p,ids=None,metal_dative=True,sanitize=False,cap_boundary=False):
    chosen=set(ids) if ids is not None else {a['id'] for a in p['atoms']}
    atoms=[a for a in p['atoms'] if a['id'] in chosen];rw=Chem.RWMol();mapping={}
    for a in atoms:
        ca=Chem.Atom(a['element']);ca.SetFormalCharge(int(a.get('charge',0)));ca.SetNoImplicit(True)
        ca.SetIsotope(int(a.get('isotope',0)));ca.SetNumRadicalElectrons(int(a.get('radical',0)))
        if a.get('chirality'):ca.SetChiralTag(Chem.ChiralType.values[int(a['chirality'])])
        ca.SetIsAromatic(bool(a.get('aromatic')));mapping[a['id']]=rw.AddAtom(ca)
    types={0.:Chem.BondType.DATIVE,1.:Chem.BondType.SINGLE,1.5:Chem.BondType.AROMATIC,2.:Chem.BondType.DOUBLE,3.:Chem.BondType.TRIPLE}
    a=index_atoms(p);caps=[]
    for b in p['bonds']:
        i,j=b['a'],b['b']
        if i in chosen and j in chosen:
            typ=types[float(b.get('order',1))]
            donor_pair=((a[i]['element'] in METALS and a[j]['element'] in ('N','O','S','P')) or (a[j]['element'] in METALS and a[i]['element'] in ('N','O','S','P')))
            if b.get('kind')=='coordinate' or metal_dative and donor_pair:
                if a[i]['element'] in METALS:i,j=j,i
                typ=Chem.BondType.DATIVE
            rw.AddBond(mapping[i],mapping[j],typ)
        elif cap_boundary and (i in chosen)!=(j in chosen) and b.get('kind')!='coordinate':
            inside,outside=(i,j) if i in chosen else (j,i)
            # Metal donor contacts are coordination rather than a missing H.
            if a[inside]['element'] in ('O','N','S','P') and a[outside]['element'] in METALS:continue
            h=Chem.Atom('H');h.SetNoImplicit(True);hi=rw.AddAtom(h);rw.AddBond(mapping[inside],hi,Chem.BondType.SINGLE)
            rp=xyz(a[inside])+unit(xyz(a[outside])-xyz(a[inside]))*(radius(a[inside]['element'])+.31)
            caps.append((hi,rp))
    mol=rw.GetMol();conf=Chem.Conformer(mol.GetNumAtoms());conf.Set3D(True)
    for atom in atoms:conf.SetAtomPosition(mapping[atom['id']],Point3D(*map(float,xyz(atom))))
    for hi,rp in caps:conf.SetAtomPosition(hi,Point3D(*map(float,rp)))
    mol.AddConformer(conf)
    if sanitize:Chem.SanitizeMol(mol)
    return mol,mapping,[i for i,r in caps]


def forcefield_model(p):
    """Prepare a calculation copy without imposing organic valence limits on Sn.

    Donor-to-metal bonds still count toward the acceptor's explicit valence in
    RDKit. Do not infer radicals or change charges to satisfy a neutral Sn
    valence of four. Organic atoms retain strict valence checks; the saved
    project and its explicit graph remain authoritative and unchanged.
    """
    mol,mapping,_=project_to_rdkit(p)
    if any(a.GetAtomicNum()==50 for a in mol.GetAtoms()):
        mol.UpdatePropertyCache(strict=False)
        for atom in mol.GetAtoms():
            if atom.GetAtomicNum()!=50:atom.UpdatePropertyCache(strict=True)
        flags=Chem.SanitizeFlags.SANITIZE_ALL ^ Chem.SanitizeFlags.SANITIZE_PROPERTIES ^ Chem.SanitizeFlags.SANITIZE_FINDRADICALS
        Chem.SanitizeMol(mol,sanitizeOps=flags)
    else:Chem.SanitizeMol(mol)
    return mol,mapping


def optimize_project(p,choice='MMFF94',scope='ligands',steps=500,cancel=None,progress=None,respect_fixed=True,allow_uff_fallback=False):
    if isinstance(steps,bool) or not isinstance(steps,(int,np.integer)) or not 1<=steps<=10000:raise ValueError('최대 반복 수는 1–10000 정수입니다.')
    if cancel and cancel.is_set():raise InterruptedError('최적화를 취소했습니다.')
    if scope!='ligands':
        out=clone(p);plan=scope_plan(out,scope,respect_fixed)
        try:
            mol,mapping=forcefield_model(out);actual=choice;notice=''
            has_sn=any(a.GetAtomicNum()==50 for a in mol.GetAtoms())
            if choice=='MMFF94' and (has_sn or not AllChem.MMFFHasAllMoleculeParams(mol)):
                reason='MMFF94에는 Sn 원자형이 없습니다.' if has_sn else 'MMFF94에 지원하지 않는 원자형이 있습니다.'
                if not allow_uff_fallback:raise ValueError(reason+' UFF를 선택하거나 ‘MMFF 미지원 시 UFF 사용’을 켜세요. MMFF94는 지원되는 리간드 내부 계산에 사용할 수 있습니다.')
                actual='UFF';notice=reason+' UFF로 계산했습니다.'
                # MMFF perception may alter aromatic flags; start UFF from a fresh model.
                mol,mapping=forcefield_model(out)
                if progress:progress(dict(message='MMFF94 → UFF · 지원 원자형 적용',percent=0))
            ff=make_forcefield(mol,actual);ff.Initialize()
        except Exception as exc:
            raise ValueError(f'{choice} 전체 구조 모델을 만들 수 없습니다: {exc}') from exc
        # RDKit's atom order is the input atom order, including fixed atoms.
        def energy_gradient(points):
            flat=points.ravel().tolist()
            return float(ff.CalcEnergy(flat)),np.asarray(ff.CalcGrad(flat)).reshape(-1,3)
        def report(value):
            if progress:progress({**value,'message':actual+' · '+value['message']})
        result=minimize_coordinates(out,plan,energy_gradient,steps,cancel,report)
        result.update(forcefield=actual,requestedForcefield=choice,fallback=actual!=choice,notice=notice,
            before_kcal_mol=result.pop('before'),after_kcal_mol=result.pop('after'))
        if any(a.GetAtomicNum()==50 for a in mol.GetAtoms()):result['note']='RDKit 표준 Sn3 UFF 원자형을 사용한 초기 정리. Sn 옥소 클러스터 전용 파라미터가 아닙니다.'
        out['metadata']['lastOptimization']=dict(at=datetime.now().isoformat(),forcefield=actual,requestedForcefield=choice,scope=scope,results=[result],
            note=notice or '전체 구조 힘장 초기 정리. rigid는 코어 기준 좌표계를 유지하고 각 연결 리간드를 강체로 이동.')
        return out,[result]
    out=clone(p);logs=[];a=index_atoms(out)
    if scope=='ligands':
        slots=[s for s in out['slots'] if s.get('ligandIds')]
        if not slots:raise ValueError('최적화할 리간드가 없습니다. 먼저 리간드를 추가하세요.')
        for k,s in enumerate(slots):
            if cancel and cancel.is_set():raise InterruptedError('최적화를 취소했습니다.')
            if progress:progress(dict(message=f"{s['id']} 최적화 {k+1}/{len(slots)}",percent=95*k/len(slots)))
            ids=[i for i in s['ligandIds'] if i in a]
            if len(ids)==1:
                logs.append({'scope':s['id'],'forcefield':choice,'skipped':'단원자 리간드에는 최적화할 내부 자유도가 없습니다.'});continue
            # Preserve branches attached to external hosts: constrain every boundary atom.
            mol,mapping,caps=project_to_rdkit(out,ids,metal_dative=False,sanitize=True,cap_boundary=True)
            ff=make_forcefield(mol,choice);chosen=set(ids);fixed=set(caps)
            for b in out['bonds']:
                if (b['a'] in chosen)!=(b['b'] in chosen):fixed.add(mapping[b['a'] if b['a'] in chosen else b['b']])
            fixed|={mapping[i] for i in ids if a[i].get('fixed')}
            for i in fixed:ff.AddFixedPoint(i)
            def fragment_progress(value):
                if progress:progress(dict(message=s['id']+' · '+value['message'],percent=95*(k+value['percent']/100)/len(slots)))
            bef,aft,status=minimize_ff(ff,steps,cancel,fragment_progress)
            for aid,i in mapping.items():
                if i not in fixed:set_xyz(a[aid],mol.GetConformer().GetAtomPosition(i))
            logs.append({'scope':s['id']+' / boundary fixed, H-capped fragment','forcefield':choice,
                'before_kcal_mol':bef,'after_kcal_mol':aft,'converged':status==0,
                'note':'고립 리간드 힘장 에너지. Sn 결합 에너지 또는 클러스터 총에너지가 아님.'})
    out['metadata']['lastOptimization']={'at':datetime.now().isoformat(),'forcefield':choice,'scope':scope,'results':logs,
        'note':'MMFF/UFF 초기 구조 정리. DFT 에너지 또는 구조 안정성 보장 아님.'}
    return out,logs


def cleanup_project(p,cancel=None,scope=None,steps=500,progress=None,respect_fixed=True):
    if scope is not None:
        plan=scope_plan(p,scope,respect_fixed)
        criteria=p['metadata'].get('contactCriteria',DEFAULTS['contact'])
        before=clashes(p,criteria)
        result=minimize_coordinates(p,plan,ContactObjective(p,radius,criteria),steps,cancel,progress)
        result.update(beforeContacts=len(before),afterContacts=len(clashes(p,criteria)),
            beforeOverlapScore=sum((r['threshold']-r['distance'])**2 for r in before),
            afterOverlapScore=sum((r['threshold']-r['distance'])**2 for r in clashes(p,criteria)),
            note='접촉 벌점 + 초기 결합/1–3 거리 및 약한 변위 제약. 점수는 임의 단위이며 힘장 에너지가 아님.')
        p['metadata']['lastCleanup']=result
        return p
    before=clone(p)
    try:
        for k,s in enumerate(p['slots']):
            if progress:progress(dict(message=f"회전 겹침 정리 {k+1}/{len(p['slots'])}",percent=95*k/max(1,len(p['slots']))))
            if s.get('kind') not in ('R','A') or not s.get('anchor') or not s.get('ligandIds'):continue
            a=index_atoms(p);ids={i for i in s['ligandIds'] if i in a};host=s['sn'][0]
            if host not in a or s['anchor'] not in a or any(a[i].get('fixed') for i in ids):continue
            boundary=[b for b in p['bonds'] if (b['a'] in ids)!=(b['b'] in ids)]
            if len(boundary)!=1:continue
            points=np.array([xyz(a[i]) for i in sorted(ids)]);origin=xyz(a[host]);axis=xyz(a[s['anchor']])-origin
            environment=dict(atoms=[v for v in p['atoms'] if v['id'] not in ids],bonds=[b for b in p['bonds'] if not({b['a'],b['b']}&ids)],metadata=p['metadata'])
            moving=[a[i] for i in sorted(ids)];moving_bonds=[b for b in p['bonds'] if {b['a'],b['b']}&ids]
            scorer=PlacementScorer(environment,moving,moving_bonds)
            guard=CorePlacement(p,[host],moving,moving_bonds)
            best_points=None;best=float('inf')
            for theta in np.linspace(0,2*math.pi,36,endpoint=False):
                if cancel and cancel.is_set():raise InterruptedError('겹침 정리를 취소했습니다.')
                candidate=(points-origin)@axis_rotation(axis,theta).T+origin
                if not guard.safe(candidate):continue
                val=scorer.score(candidate)
                if val<best:best=val;best_points=candidate.copy()
            if best_points is None:raise ValueError(f"{s['id']}: 코어 내부로 들어가지 않는 리간드 배치를 찾지 못했습니다. 연결 원자나 리간드 구조를 바꿔 다시 시도하세요.")
            for i,r in zip(sorted(ids),best_points):set_xyz(a[i],r)
    except Exception:
        p.clear();p.update(before);raise
    return p


def bond_audit(p,scale=1.25,metal_max=2.85):
    """Keep explicit bonds authoritative. ASE supplies geometric candidates, not proof."""
    a=index_atoms(p);known={bond_key(b['a'],b['b']):b for b in p['bonds']};out=[]
    if not a:return out
    aa=p['atoms'];atoms=Atoms([v['element'] for v in aa],positions=[xyz(v) for v in aa],pbc=False)
    cutoffs=natural_cutoffs(atoms,mult=scale)
    # Broaden metal centers so that long donor contacts are not discarded by covalent radii.
    for i,v in enumerate(aa):
        if v['element'] in METALS:cutoffs[i]=max(cutoffs[i],metal_max-0.6)
    ixs,jxs,ds=neighbor_list('ijd',atoms,cutoffs,self_interaction=False)
    seen=set()
    for i,j,d in zip(ixs,jxs,ds):
        i,j=int(i),int(j);u,v=aa[i],aa[j];key=bond_key(u['id'],v['id'])
        if key in seen or key in known:continue
        seen.add(key)
        if d<.45:continue
        metal=u['element'] in METALS or v['element'] in METALS
        if metal:
            if u['element'] in METALS and v['element'] in METALS:limit=3.3
            elif 'C' in (u['element'],v['element']):limit=2.55
            else:limit=metal_max
            if d>limit:continue
        else:
            limit=(radius(u['element'])+radius(v['element']))*scale
            if d>limit or u['element']==v['element']=='H':continue
        out.append({'a':key[0],'b':key[1],'distance':float(d),'order':1.,
                    'kind':'coordinate' if metal and ({u['element'],v['element']}&{'O','N','S','P'}) else 'covalent',
                    'source':'ASE neighbor candidate + metal donor rule' if metal else 'ASE neighbor candidate',
                    'status':'검토 후보 / 자동 확정 아님'})
    for b in p['bonds']:
        u,v=a[b['a']],a[b['b']];d=float(np.linalg.norm(xyz(u)-xyz(v)))
        metal=u['element'] in METALS or v['element'] in METALS
        limit=metal_max+0.3 if metal else 1.7*(radius(u['element'])+radius(v['element']))
        out.append({**b,'distance':d,'status':'긴 결합: 확인 필요' if d>limit else '기존 명시 결합 유지'})
    return out


def infer_xyz_bonds(p,charge=0):
    if not p['atoms']:return p
    if not any(a['element'] in METALS for a in p['atoms']):
        try:
            mol,_m,_=project_to_rdkit(p,metal_dative=False)
            rdDetermineBonds.DetermineBonds(mol,charge=int(charge),embedChiral=True)
            for b in mol.GetBonds():
                u=p['atoms'][b.GetBeginAtomIdx()]['id'];v=p['atoms'][b.GetEndAtomIdx()]['id']
                add_bond(p,u,v,b.GetBondTypeAsDouble(),'covalent','RDKit xyz2mol inference')
            for i,atom in enumerate(mol.GetAtoms()):p['atoms'][i].update(charge=atom.GetFormalCharge(),aromatic=atom.GetIsAromatic(),chirality=int(atom.GetChiralTag()))
            p['metadata']['bondInference']='RDKit xyz2mol; charge='+str(charge)
            return p
        except Exception as exc:p['metadata']['bondInferenceNote']=str(exc)
    rows=bond_audit(p)
    for row in rows:add_bond(p,row['a'],row['b'],row['order'],row['kind'],'ASE distance inference / tentative')
    p['metadata']['bondInference']='ASE 거리 후보를 초기 연결로 표시. 금속 결합차수/전하 미확정; 결합 검사에서 수정하세요.'
    return p

# ----------------------------- Import / export -------------------------------
def export_xyz(p):
    return f"{len(p['atoms'])}\n{p['title']} | Å | charge={p['metadata'].get('totalCharge','unset')}\n"+'\n'.join(
        f"{a['element']:<3} {a['x']: .9f} {a['y']: .9f} {a['z']: .9f}" for a in p['atoms'])+'\n'

def new_project():
    return {'version':3,'title':'Imported structure','atoms':[],'bonds':[],'slots':[],
            'metadata':{'totalCharge':None,'requiresChargeReview':True}}

def read_structure(path):
    path=Path(path);ext=path.suffix.lower()
    if ext in ('.json','.tinoxo','.html','.htm'):
        text=read_unicode_text(path)
        if ext in ('.html','.htm'):
            match=re.search(r'<script[^>]*\bid=["\']initialProject["\'][^>]*>(.*?)</script>',text,re.S|re.I)
            lib=re.search(r'<script[^>]*\bid=["\']structureLibrary["\'][^>]*>(.*?)</script>',text,re.S|re.I)
            if not match:raise ValueError('TinOxoStudio가 저장한 HTML 프로젝트가 아닙니다.')
            project=json.loads(match.group(1));bank=json.loads(lib.group(1)) if lib else None
            extra=re.search(r'<script[^>]*\bid=["\']nativeSettings["\'][^>]*>(.*?)</script>',text,re.S|re.I)
            return validate_project(project),bank,json.loads(extra.group(1)) if extra else None
        data=json.loads(text)
        if 'project' in data:return validate_project(data['project']),data.get('bank'),data.get('settings')
        if 'entries' in data:
            entries=data['entries']
            if not entries:raise ValueError('빈 구조 보관함입니다.')
            entry=next((e for e in entries if e['id']==data.get('activeId')),entries[0]);return validate_project(entry['project']),data,None
        return validate_project(data),None,None
    p=new_project();p['title']=path.stem
    if ext in ('.mol','.sdf','.mol2','.pdb'):
        if ext=='.mol':m=Chem.MolFromMolFile(str(path),sanitize=False,removeHs=False)
        elif ext=='.sdf':m=next((v for v in Chem.SDMolSupplier(str(path),sanitize=False,removeHs=False) if v is not None),None)
        elif ext=='.mol2':m=Chem.MolFromMol2File(str(path),sanitize=False,removeHs=False)
        else:m=Chem.MolFromPDBFile(str(path),sanitize=False,removeHs=False,proximityBonding=False)
        if m is None:raise ValueError('RDKit이 구조 파일을 읽지 못했습니다.')
        conf=m.GetConformer()
        for i,a in enumerate(m.GetAtoms()):
            pos=conf.GetAtomPosition(i);p['atoms'].append({'id':i+1,'element':a.GetSymbol(),'x':pos.x,'y':pos.y,'z':pos.z,
                'charge':a.GetFormalCharge(),'isotope':a.GetIsotope(),'aromatic':a.GetIsAromatic(),'core':False})
        for b in m.GetBonds():add_bond(p,b.GetBeginAtomIdx()+1,b.GetEndAtomIdx()+1,b.GetBondTypeAsDouble(),
            'coordinate' if b.GetBondType()==Chem.BondType.DATIVE else 'covalent','file explicit')
        if ext=='.pdb' and not p['bonds']:infer_xyz_bonds(p)
        p['metadata']['totalCharge']=sum(a['charge'] for a in p['atoms'])
    else:
        at=ase.io.read(str(path),index=-1)
        for i,(s,r) in enumerate(zip(at.get_chemical_symbols(),at.positions)):
            p['atoms'].append(dict(id=i+1,element=s,x=float(r[0]),y=float(r[1]),z=float(r[2]),core=False,charge=0))
        p['metadata']['originalCell']=at.cell.array.tolist();p['metadata']['originalPBC']=at.pbc.tolist()
        if at.pbc.any():p['metadata']['periodicWarning']='화면과 접촉 검사는 단일 분자/클러스터 기준입니다. 주기경계 결합은 자동 확정하지 않습니다.'
        infer_xyz_bonds(p)
    return validate_project(p),None,None


def export_sdf(p):
    # V3000 preserves dative bonds as type 9 and atom formal charges as supplied.
    idx={a['id']:i+1 for i,a in enumerate(p['atoms'])}
    lines=[p['title'],'     TINOXO         3D','', '  0  0  0     0  0            999 V3000',
           'M  V30 BEGIN CTAB',f"M  V30 COUNTS {len(p['atoms'])} {len(p['bonds'])} 0 0 0",'M  V30 BEGIN ATOM']
    for a in p['atoms']:
        extra=(f" CHG={a['charge']}" if a.get('charge') else '')+(f" MASS={a['isotope']}" if a.get('isotope') else '')
        lines.append(f"M  V30 {idx[a['id']]} {a['element']} {a['x']:.8f} {a['y']:.8f} {a['z']:.8f} 0{extra}")
    lines+=['M  V30 END ATOM','M  V30 BEGIN BOND']
    for i,b in enumerate(p['bonds']):
        order=9 if b.get('kind')=='coordinate' or b.get('order')==0 else 4 if b['order']==1.5 else int(b['order'])
        lines.append(f"M  V30 {i+1} {order} {idx[b['a']]} {idx[b['b']]}")
    lines+=['M  V30 END BOND','M  V30 END CTAB','M  END',
        '>  <TOTAL_CHARGE_USER>',str(p['metadata'].get('totalCharge','unset')),'',
        '>  <ATOM_CHARGE_NOTE>','Per-atom charges may be unassigned for metal core; total charge is separate.','',
        '>  <TINOXO_METADATA>',json.dumps(p['metadata'],ensure_ascii=False),'','$$$$','']
    return '\n'.join(lines)


def export_pdb(p):
    idx={a['id']:i+1 for i,a in enumerate(p['atoms'])};lines=['REMARK TinOxoStudio: PDB does not preserve bond orders / charge metadata.']
    for a in p['atoms']:
        i=idx[a['id']];lines.append(f"HETATM{i:5d} {a['element']+str(i%100):<4} LIG A   1    {a['x']:8.3f}{a['y']:8.3f}{a['z']:8.3f}  1.00  0.00          {a['element']:>2}")
    for aid,ns in adjacency(p).items():
        for k in range(0,len(ns),4):lines.append(f'CONECT{idx[aid]:5d}'+''.join(f'{idx[i]:5d}' for i in ns[k:k+4]))
    return '\n'.join(lines+['END',''])


def portable_html(p,bank,settings):
    if len(p['atoms'])>5000 or any(len(e.get('project',{}).get('atoms',[]))>5000 for e in bank.get('entries',[])):
        raise ValueError('기존 HTML 편집기는 구조당 5,000원자까지 지원합니다. 더 큰 구조는 Python 프로젝트 JSON으로 저장하세요.')
    text=zlib.decompress(base64.b64decode(LEGACY_HTML)).decode()
    def inject(text_,id_,value):
        raw=json.dumps(value,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')
        pat=r'(<script\b[^>]*\bid=["\']'+id_+r'["\'][^>]*>).*?(</script>)'
        return re.sub(pat,lambda m:m.group(1)+raw+m.group(2),text_,flags=re.S|re.I)
    b=clone(bank);b.setdefault('version',1);b.setdefault('revision',0);b.setdefault('activeId',None)
    b.setdefault('trash',[]);b.setdefault('updatedAt',datetime.now().isoformat());b.setdefault('id',uuid.uuid4().hex)
    # Existing browser editor understands the common atom/bond/project fields.
    text=inject(text,'initialProject',p);text=inject(text,'structureLibrary',b)
    notice='<div style="background:#153b4a;color:white;padding:8px">Python 4.1 project snapshot · 이 HTML은 기존 웹 편집기입니다. 새 최적화/검사/Gaussian 기능은 TinOxoStudio.py에서 실행하세요.</div>'
    text=text.replace('<body>','<body>'+notice,1)
    raw=json.dumps(settings,ensure_ascii=False).replace('<','\\u003c')
    return text.replace('</body>',f'<script id="nativeSettings" type="application/json">{raw}</script></body>')

# --------------------------- Gaussian 16 builder -----------------------------
METHODS=['B3LYP','PBE1PBE','PBEPBE','BLYP','BP86','M06','M062X','M06L','TPSSh','TPSSTPSS',
         'wB97XD','CAM-B3LYP','LC-wPBE','B97D','APFD','HF','MP2','CCSD','CCSD(T)']
EXCHANGE=['B','PBE','mPW','G96','S'];CORRELATION=['LYP','P86','PBE','PW91','VWN']
VALID_XC={'BLYP','BP86','BPBE','BPW91','PBEPBE','PBELYP','mPWLYP','mPWPW91','G96LYP','SVWN','SLYP'}
BASIS_SETS=['Def2SVP','Def2TZVP','Def2TZVPP','Def2QZVP','SDD','LANL2DZ','STO-3G','3-21G',
            '6-31G(d)','6-31G(d,p)','6-31+G(d,p)','6-311G(d,p)','6-311++G(d,p)',
            'cc-pVDZ','cc-pVTZ','aug-cc-pVDZ','aug-cc-pVTZ']
GAUSSIAN_JOBS={'단일점 / 전자구조':'SP','구조 최적화':'Opt','최적화 + 진동수':'Opt Freq','진동수':'Freq',
               'TD-DFT / 전자여기':'TD','NMR':'NMR','분극률':'Polar','힘 계산':'Force','전이상태 탐색':'TS'}

def gaussian_defaults(p):
    charge=p['metadata'].get('totalCharge');q=int(charge) if charge is not None else 0
    ne=sum(atomic_numbers[a['element']] for a in p['atoms'])-q
    return {'title':'Tin oxo cluster','method':'B3LYP','spin':'Auto','basis_mode':'mixed','basis':'Def2SVP',
        'charge':q,'multiplicity':1 if ne%2==0 else 2,'job':'구조 최적화','cpus':8,'memory':'8GB','checkpoint':'tinoxo.chk',
        'scf':'XQC','scf_max':512,'scf_tight':True,'grid':'UltraFine','opt_tight':True,'opt_cycles':200,
        'dispersion':'None','nosymm':True,'population':'Regular','solvent':'None','solvation':'SMD',
        'states':10,'root':1,'freeze':'None','extra':'','additional':'','basis_by_element':{},'ecp_by_element':{}}

def validate_basis(element,basis):
    z=atomic_numbers[element];b=basis.lower()
    if b.startswith('def2') and z>86:raise ValueError(f'{element}: Gaussian 내장 def2 범위를 벗어납니다. 검증한 외부 GenECP를 사용하세요.')
    if b.startswith('def2') and 58<=z<=71:raise ValueError(f'{element}: Gaussian 16 내장 def2 표의 란탄족 지원 범위를 벗어납니다. 검증한 외부 GenECP를 사용하세요.')
    if z>36 and (b.startswith(('6-31','6-311','cc-pv','aug-cc-pv'))):
        raise ValueError(f'{element}에 {basis}를 그대로 적용할 수 없습니다. Sn에는 def2 + ECP 또는 SDD 등을 지정하세요.')
    if not re.fullmatch(r'[A-Za-z0-9+*(),.\-]+',basis):raise ValueError('기저함수 키워드에 허용되지 않는 문자가 있습니다.')

def build_gaussian(p,options):
    validate_project(p)
    if not p['atoms']:raise ValueError('저장할 원자가 없습니다.')
    o={**gaussian_defaults(p),**options};method=o['method'].strip();basis=o['basis'].strip();q=int(o['charge']);mult=int(o['multiplicity'])
    if not re.fullmatch(r'[A-Za-z0-9(),+\-]+',method):raise ValueError('방법/XC 키워드는 공백 없는 Gaussian 키워드로 입력하세요.')
    ne=sum(atomic_numbers[a['element']] for a in p['atoms'])-q
    if ne<1 or mult<1 or mult-1>ne or (ne-(mult-1))%2:raise ValueError(f'전자수 {ne}와 다중도 {mult}의 홀짝이 맞지 않습니다. 전하와 다중도를 확인하세요.')
    if int(o['cpus'])<1 or int(o['cpus'])>4096:raise ValueError('CPU 수는 1–4096 범위입니다.')
    if min(int(o['scf_max']),int(o['opt_cycles']),int(o['states']))<1:raise ValueError('SCF/최적화 반복수와 TD 상태수는 양수여야 합니다.')
    memory=str(o['memory']).strip().upper()
    if not re.fullmatch(r'[1-9][0-9]*(?:KB|MB|GB|TB|KW|MW|GW)',memory):raise ValueError('%Mem 예: 8GB, 16000MB')
    chk=str(o['checkpoint']).strip()
    if not chk or any(c in chk for c in '\n\r%') or not chk.isascii():raise ValueError('체크포인트 경로는 ASCII 한 줄로 입력하세요.')
    if any(c.isspace() for c in chk):raise ValueError('체크포인트 경로에는 공백을 사용하지 마세요.')
    job=GAUSSIAN_JOBS.get(o['job'],o['job']);elements=sorted({a['element'] for a in p['atoms']},key=lambda s:atomic_numbers[s]);warnings=[]
    if o.get('spin')=='ROHF':
        if method.upper()!='HF':raise ValueError('ROHF 선택은 HF 방법에서 사용하세요.')
        method='ROHF'
    elif o.get('spin') in ('R','U'):
        if o['spin']=='R' and mult!=1:raise ValueError('R 폐각 파동함수는 다중도 1을 지정하세요.')
        method=o['spin']+method
    mode=o.get('basis_mode','mixed');basis_tail='';basis_keyword=basis;ecps={};groups=defaultdict(list)
    if mode!='custom':
        for s in elements:
            bs=o.get('basis_by_element',{}).get(s,basis) if mode=='mixed' else basis
            validate_basis(s,bs);groups[bs].append(s)
            ec=o.get('ecp_by_element',{}).get(s,'Auto') if mode=='mixed' else 'Auto'
            if ec=='Auto':
                if bs.lower().startswith('def2') and 37<=atomic_numbers[s]<=86:ec='Def2'
                elif bs.upper() in ('SDD','LANL2DZ') and atomic_numbers[s]>18:ec=bs
                else:ec='None'
            if ec!='None':ecps[ec]=ecps.get(ec,[])+[s]
        needs_general=mode=='mixed' or bool(ecps) and basis.lower().startswith('def2')
        if needs_general:
            basis_keyword='GenECP' if ecps else 'Gen'
            lines=[]
            for bs,ss in groups.items():lines+=[' '.join(ss)+' 0',bs,'****']
            if ecps:
                lines.append('')
                for ec,ss in ecps.items():lines+=[' '.join(ss)+' 0',ec]
            basis_tail='\n'.join(lines)+'\n\n'
    else:
        basis_keyword=o.get('custom_keyword','GenECP')
        if basis_keyword not in ('Gen','GenECP'):raise ValueError('외부 기저함수는 Gen 또는 GenECP를 선택하세요.')
        basis_tail=o.get('custom_basis','').strip()+'\n\n'
        if '****' not in basis_tail:raise ValueError('외부 기저함수 블록에 **** 구분자가 없습니다.')
        basis_part=basis_tail.split('\n\n',1)[0];covered=set()
        for line in basis_part.splitlines():
            tokens=line.split()
            if tokens and tokens[-1]=='0':covered|={t.lstrip('-') for t in tokens[:-1] if t.lstrip('-') in SYMBOLS}
        if not set(elements)<=covered:raise ValueError('외부 기저함수에 빠진 원소: '+', '.join(sorted(set(elements)-covered)))
        if basis_keyword=='GenECP' and '\n\n' not in basis_tail.strip():raise ValueError('GenECP에는 기저함수와 ECP 사이 빈 줄 및 ECP 블록이 필요합니다.')
        warnings.append('사용자 외부 기저함수의 수치 및 ECP 전자수는 Gaussian에서 최종 확인해야 합니다.')
    route=[method+'/'+basis_keyword]
    frozen=set()
    if o.get('freeze')=='Core':frozen={a['id'] for a in p['atoms'] if a.get('core')}
    elif o.get('freeze')=='Fixed':frozen={a['id'] for a in p['atoms'] if a.get('fixed')}
    isopt='Opt' in job or job=='TS'
    if frozen and not isopt:raise ValueError('원자 고정은 구조 최적화 작업에서 선택하세요.')
    if frozen and len(frozen)==len(p['atoms']):raise ValueError('모든 원자가 고정되어 있습니다. 이동할 원자를 남겨주세요.')
    if isopt:
        opt=['Tight'] if o.get('opt_tight') else []
        opt+=['MaxCycles='+str(int(o['opt_cycles']))]
        if frozen:opt+=['Cartesian']
        if job=='TS':opt+=['TS','CalcFC','NoEigenTest'];warnings.append('TS는 적절한 초기 추정과 진동수의 허수모드 확인이 필요합니다.')
        route.append('Opt=('+','.join(opt)+')')
        if 'Freq' in job:route.append('Freq')
    elif job=='TD':
        if not 1<=int(o['root'])<=int(o['states']):raise ValueError('TD Root는 1–NStates 범위입니다.')
        route.append(f"TD=(NStates={int(o['states'])},Root={int(o['root'])})")
    else:route.append(job)
    scf=[]
    if o.get('scf_tight'):scf.append('Tight')
    if o.get('scf','None')!='None':scf.append(o['scf'])
    scf.append('MaxCycle='+str(int(o['scf_max'])))
    route.append('SCF=('+','.join(scf)+')')
    if o.get('grid','None')!='None' and method.upper().lstrip('RU') not in ('HF','MP2','CCSD','CCSD(T)','ROHF'):route.append('Integral='+o['grid'])
    if o.get('nosymm'):route.append('NoSymm')
    disp=o.get('dispersion','None')
    if disp!='None':
        if method.upper().lstrip('RU') in ('WB97XD','B97D','APFD'):raise ValueError('분산이 포함된 방법에 GD3/GD3BJ를 중복 추가하지 마세요.')
        route.append('EmpiricalDispersion='+disp)
    if o.get('population','None')!='None':route.append('Pop='+o['population'])
    if o.get('solvent','None')!='None':
        solvent=o['solvent'].strip()
        if not re.fullmatch('[A-Za-z0-9-]+',solvent):raise ValueError('용매명은 Gaussian 키워드로 입력하세요.')
        route.append(f"SCRF=({o['solvation']},Solvent={solvent})")
    extra=o.get('extra','').strip()
    if any(c in extra for c in '\n\r#%') or re.search(r'Geom\s*=\s*\(?\s*(?:AllCheck|Check)',extra,re.I):raise ValueError('추가 route에는 한 줄 키워드를 입력하세요. Geom=Check/AllCheck는 현재 좌표 입력과 함께 사용할 수 없습니다.')
    if extra:route.append(extra)
    title=str(o['title']).strip() or 'Tin oxo cluster'
    if '\n' in title or not title.isascii() or any(c in title for c in '#@!\\'):raise ValueError('Gaussian 제목은 # @ ! 없이 ASCII 한 줄로 입력하세요.')
    lines=[f'%NProcShared={int(o["cpus"])}',f'%Mem={memory}',f'%Chk={chk}','#p '+' '.join(route),'',title,'',f'{q} {mult}']
    for a in p['atoms']:
        freeze_flag=(' -1' if a['id'] in frozen else ' 0') if frozen else ''
        lines.append(f"{a['element']:<3}{freeze_flag} {a['x']: .9f} {a['y']: .9f} {a['z']: .9f}")
    lines.append('');text='\n'.join(lines)+'\n'
    if basis_tail:text+=basis_tail
    if o.get('additional','').strip():text+=o['additional'].strip()+'\n\n'
    if p['metadata'].get('requiresChargeReview') or p['metadata'].get('totalCharge') is None:
        warnings.append('편집한 골격/리간드의 총전하와 다중도는 사용자가 확인해야 합니다. 원자별 형식전하 합으로 자동 확정하지 않습니다.')
    if any(a['element'] in METALS for a in p['atoms']):warnings.append('금속의 배위결합을 Gaussian 연결차수로 강제하지 않았습니다. Cartesian 핵 좌표와 지정 전하/다중도를 사용합니다.')
    return text,{'electrons':ne,'warnings':warnings,'ecp':ecps,'route':' '.join(route)}

# --------------------- Unicode / bilingual font handling ----------------------
KOREAN_FONT_CHOICES=('맑은고딕','굴림')
ENGLISH_FONT_CHOICES=('Arial','Calibri')
FONT_ALIASES={'맑은고딕':('Malgun Gothic','맑은 고딕','맑은고딕'),
              '굴림':('Gulim','굴림'), 'Arial':('Arial',), 'Calibri':('Calibri',)}
HANGUL_RE=re.compile(r'[\u1100-\u11ff\u3130-\u318f\uac00-\ud7af]+')
FONT_REGISTRATION={'registered':[],'errors':[]}
TEXT_RENDERING={'configured':False,'mode':'native','errors':[]}

def configure_text_rendering():
    """Configure this process before creating Tk; never change desktop settings."""
    if TEXT_RENDERING['configured']:return TEXT_RENDERING
    TEXT_RENDERING['configured']=True
    try:
        import ctypes,ctypes.util
        if sys.platform=='win32':
            # Prevent Windows from stretching a low-DPI bitmap of the whole UI.
            user32=ctypes.windll.user32
            try:
                fn=user32.SetProcessDpiAwarenessContext;fn.argtypes=[ctypes.c_void_p];fn.restype=ctypes.c_bool
                ok=fn(ctypes.c_void_p(-4)) # per-monitor V2
            except AttributeError:ok=False
            if not ok:
                try:ctypes.windll.shcore.SetProcessDpiAwareness(2)
                except (AttributeError,OSError):user32.SetProcessDPIAware()
            TEXT_RENDERING['mode']='Windows per-monitor DPI / native text'
        elif sys.platform.startswith('linux'):
            lib=ctypes.CDLL(ctypes.util.find_library('fontconfig') or 'libfontconfig.so.1')
            lib.FcInitLoadConfig.argtypes=[];lib.FcInitLoadConfig.restype=ctypes.c_void_p
            lib.FcConfigParseAndLoadFromMemory.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_int]
            lib.FcConfigParseAndLoadFromMemory.restype=ctypes.c_int
            lib.FcConfigBuildFonts.argtypes=[ctypes.c_void_p];lib.FcConfigBuildFonts.restype=ctypes.c_int
            lib.FcConfigSetCurrent.argtypes=[ctypes.c_void_p];lib.FcConfigSetCurrent.restype=ctypes.c_int
            lib.FcConfigDestroy.argtypes=[ctypes.c_void_p]
            # Grayscale avoids colored subpixel fringes over remote X11. Outline
            # glyphs with hinting avoid small embedded CJK bitmap strikes.
            rule=b'''<?xml version="1.0"?><!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">
<fontconfig><match target="font">
<edit name="antialias" mode="assign"><bool>true</bool></edit>
<edit name="hinting" mode="assign"><bool>true</bool></edit>
<edit name="hintstyle" mode="assign"><const>hintfull</const></edit>
<edit name="rgba" mode="assign"><const>none</const></edit>
<edit name="embeddedbitmap" mode="assign"><bool>false</bool></edit>
</match></fontconfig>'''
            config=lib.FcInitLoadConfig()
            if not config:raise OSError('Fontconfig configuration allocation failed')
            try:
                if not lib.FcConfigParseAndLoadFromMemory(config,rule,1) or not lib.FcConfigBuildFonts(config) or not lib.FcConfigSetCurrent(config):
                    raise OSError('Fontconfig text configuration failed')
            finally:lib.FcConfigDestroy(config)
            TEXT_RENDERING['mode']='Xft / outline glyphs / grayscale antialias / full hinting'
    except (OSError,AttributeError) as exc:TEXT_RENDERING['errors'].append(str(exc))
    return TEXT_RENDERING

def read_unicode_text(path):
    """UTF-8/BOM is canonical; migrate legacy Korean CP949 without replacement."""
    raw=Path(path).read_bytes()
    try:return raw.decode('utf-8-sig')
    except UnicodeDecodeError:
        try:return raw.decode('cp949')
        except UnicodeDecodeError as exc:raise ValueError('텍스트를 UTF-8 또는 CP949로 읽을 수 없습니다: '+str(path)) from exc

def font_directories():
    dirs=[Path(__file__).resolve().parent/'fonts',Path.home()/'.local/share/fonts/tinoxo-studio']
    if os.environ.get('TINOXO_FONT_DIR'):dirs.insert(0,Path(os.environ['TINOXO_FONT_DIR']).expanduser())
    return dirs

def register_local_fonts():
    """Register bundled/user fonts privately; no root permissions or downloads."""
    paths=sorted({str(p.resolve()) for d in font_directories() if d.is_dir() for p in d.rglob('*')
                  if p.is_file() and p.suffix.lower() in ('.ttf','.ttc','.otf')})
    result={'registered':[],'errors':[]}
    try:
        if sys.platform.startswith('linux'):
            import ctypes,ctypes.util
            lib=ctypes.CDLL(ctypes.util.find_library('fontconfig') or 'libfontconfig.so.1')
            lib.FcConfigAppFontAddFile.argtypes=[ctypes.c_void_p,ctypes.c_char_p];lib.FcConfigAppFontAddFile.restype=ctypes.c_int
            lib.FcConfigBuildFonts.argtypes=[ctypes.c_void_p];lib.FcConfigBuildFonts.restype=ctypes.c_int
            for path in paths:
                if lib.FcConfigAppFontAddFile(None,os.fsencode(path)):result['registered'].append(path)
                else:result['errors'].append('폰트 등록 실패: '+Path(path).name)
            if paths:lib.FcConfigBuildFonts(None)
        elif sys.platform=='win32':
            import ctypes
            for path in paths:
                add=ctypes.windll.gdi32.AddFontResourceExW
                add.argtypes=[ctypes.c_wchar_p,ctypes.c_uint,ctypes.c_void_p];add.restype=ctypes.c_int
                if add(str(path),0x10,None):result['registered'].append(path)
                else:result['errors'].append('폰트 등록 실패: '+Path(path).name)
    except (OSError,AttributeError) as exc:result['errors'].append(str(exc))
    FONT_REGISTRATION.update(result)
    return result


def font_file_for_family(family):
    """Find the same Fontconfig face used by Tk for raster image export."""
    if sys.platform.startswith('linux'):
        import ctypes,ctypes.util
        try:
            lib=ctypes.CDLL(ctypes.util.find_library('fontconfig') or 'libfontconfig.so.1')
            lib.FcNameParse.argtypes=[ctypes.c_char_p];lib.FcNameParse.restype=ctypes.c_void_p
            lib.FcConfigSubstitute.argtypes=[ctypes.c_void_p,ctypes.c_void_p,ctypes.c_int]
            lib.FcDefaultSubstitute.argtypes=[ctypes.c_void_p]
            lib.FcFontMatch.argtypes=[ctypes.c_void_p,ctypes.c_void_p,ctypes.POINTER(ctypes.c_int)];lib.FcFontMatch.restype=ctypes.c_void_p
            lib.FcPatternGetString.argtypes=[ctypes.c_void_p,ctypes.c_char_p,ctypes.c_int,ctypes.POINTER(ctypes.c_char_p)]
            lib.FcPatternDestroy.argtypes=[ctypes.c_void_p]
            pattern=lib.FcNameParse(str(family).encode('utf-8'))
            if not pattern:return None
            match=None
            try:
                lib.FcConfigSubstitute(None,pattern,0);lib.FcDefaultSubstitute(pattern);result=ctypes.c_int();match=lib.FcFontMatch(None,pattern,ctypes.byref(result))
                file=ctypes.c_char_p()
                if match and lib.FcPatternGetString(match,b'file',0,ctypes.byref(file))==0 and file.value:return os.fsdecode(file.value)
            finally:
                if match:lib.FcPatternDestroy(match)
                lib.FcPatternDestroy(pattern)
        except (OSError,AttributeError):pass
    return None

def normalize_font_preferences(settings):
    old=str(settings.get('font_family',''))
    if settings.get('korean_font') not in KOREAN_FONT_CHOICES:
        settings['korean_font']='굴림' if old in FONT_ALIASES['굴림'] else '맑은고딕'
    if settings.get('english_font') not in ENGLISH_FONT_CHOICES:
        settings['english_font']='Calibri' if old.casefold()=='calibri' else 'Arial'
    try:settings['font_size']=max(8,min(24,int(settings.get('font_size',11))))
    except (ValueError,TypeError):settings['font_size']=11
    return settings

def resolve_font_choices(settings,families):
    normalize_font_preferences(settings)
    def key(s):return unicodedata.normalize('NFC',str(s)).casefold().replace(' ','').replace('-','')
    installed={key(s):s for s in families}
    def lookup(names):return next((installed[key(n)] for n in names if key(n) in installed),None)
    ko_req=settings['korean_font'];en_req=settings['english_font']
    ko=lookup(FONT_ALIASES[ko_req]);en=lookup(FONT_ALIASES[en_req]);notes=[]
    if not ko:
        ko=lookup(('NanumGothic','Nanum Gothic','Noto Sans CJK KR','Noto Sans KR','UnDotum'))
        if ko:notes.append(f'{ko_req} 미설치 → {ko}')
        else:
            ko=lookup(('Noto Sans CJK JP','Noto Sans CJK SC')) or 'TkDefaultFont'
            notes.append('한글 글꼴 확인 필요: 번들 fonts 폴더 또는 한글 TTF를 함께 설치하세요.')
    if not en:
        en=lookup(('Carlito','Liberation Sans','DejaVu Sans','Helvetica')) or 'TkDefaultFont'
        notes.append(f'{en_req} 미설치 → {en}')
    return {'korean':ko,'english':en,'notes':notes}

class AppFonts:
    def __init__(self,root,settings):
        self.root=root;self.signature=None;self.named={};self.update(settings)
    def update(self,settings):
        resolved=resolve_font_choices(settings,tkfont.families(self.root));self.resolved=resolved
        size=int(settings['font_size']);sig=(resolved['korean'],resolved['english'],size)
        settings['font_family']=resolved['korean'] # compatible with old project consumers
        if sig==self.signature:return
        self.signature=sig
        specs={'ui':(resolved['korean'],size,'normal'),'heading':(resolved['korean'],size+2,'bold'),
               'small':(resolved['korean'],max(10,size-1),'normal'),'english':(resolved['english'],size,'normal'),
               'english_bold':(resolved['english'],size,'bold')}
        for name,(family,point_size,weight) in specs.items():
            if family=='TkDefaultFont':family=tkfont.nametofont('TkDefaultFont').actual('family')
            if name not in self.named:self.named[name]=tkfont.Font(root=self.root,family=family,size=point_size,weight=weight)
            else:self.named[name].configure(family=family,size=point_size,weight=weight)
        for name in ('TkDefaultFont','TkMenuFont','TkHeadingFont','TkCaptionFont','TkTooltipFont'):
            try:tkfont.nametofont(name).configure(family=self.named['ui'].actual('family'),size=size)
            except tk.TclError:pass
        for name in ('TkTextFont','TkFixedFont'):
            try:tkfont.nametofont(name).configure(family=self.named['english'].actual('family'),size=size)
            except tk.TclError:pass
    def for_text(self,text,bold=False):
        return self.named['heading' if bold and HANGUL_RE.search(str(text)) else 'ui' if HANGUL_RE.search(str(text)) else 'english_bold' if bold else 'english']
    def style_text(self,widget):
        if not widget.winfo_exists():return
        widget.configure(font=self.named['english']);widget.tag_configure('tinoxo_hangul',font=self.named['ui'])
        widget.tag_remove('tinoxo_hangul','1.0','end')
        for m in HANGUL_RE.finditer(widget.get('1.0','end-1c')):
            widget.tag_add('tinoxo_hangul',f'1.0+{m.start()}c',f'1.0+{m.end()}c')
    def apply_widgets(self,parent):
        for widget in parent.winfo_children():
            try:
                if isinstance(widget,tk.Menu):
                    widget.configure(font=self.named['ui'])
                    for i in range((widget.index('end') or 0)+1):
                        if widget.type(i) not in ('separator','tearoff'):widget.entryconfigure(i,font=self.for_text(widget.entrycget(i,'label')))
                elif isinstance(widget,(ttk.Entry,ttk.Combobox,tk.Entry)):
                    widget.configure(font=self.for_text(widget.get()))
                    if not getattr(widget,'_tinoxo_font_hook',False):
                        def refresh_font(event,w=widget):
                            if w.winfo_exists():w.configure(font=self.for_text(w.get()))
                        widget.bind('<KeyRelease>',refresh_font,add='+')
                        widget.bind('<<ComboboxSelected>>',refresh_font,add='+')
                        widget._tinoxo_font_hook=True
                elif isinstance(widget,tk.Text):self.style_text(widget)
            except tk.TclError:pass
            self.apply_widgets(widget)

