    def change_sn_c(self):
        length=float(self.snc_var.get())
        if not 1.8<=length<=2.8:raise ValueError('Sn–C 길이는 1.80–2.80 Å 범위로 입력하세요.')
        a=index_atoms(self.project);g=adjacency(self.project);moves={};slots=[]
        for s in self.project['slots']:
            if s.get('kind')!='R' or not s.get('anchor'):continue
            host=s['sn'][0];anchor=s['anchor'];connected={anchor};todo=[anchor]
            while todo:
                current=todo.pop()
                for nxt in g[current]:
                    if nxt==host or nxt in connected:continue
                    if a[nxt].get('core'):raise ValueError('R 리간드가 다른 코어 원자에도 연결되어 있습니다. 개별 결합을 편집하세요.')
                    connected.add(nxt);todo.append(nxt)
            vec=xyz(a[anchor])-xyz(a[host]);shift=unit(vec)*length-vec
            if set(moves)&connected:raise ValueError('R 리간드 사이 연결이 있어 일괄 이동할 수 없습니다.')
            moves.update({i:shift for i in connected});slots.append(s)
        if not slots:raise ValueError('길이를 변경할 R 리간드가 없습니다.')
        self.snapshot()
