        ttk.Combobox(general,textvariable=fps,values=['15','20','30','60'],state='readonly').pack(anchor='w',pady=3)
        ttk.Checkbutton(general,text='회전 / 이동 중 경량 표시 (권장)',variable=lod).pack(anchor='w',pady=3)
